SPARQL_Query:
PREFIX iof-core: <https://spec.industrialontologies.org/ontology/core/Core/> .
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
PREFIX sdk: <http://asu.edu/semantics/SUDOKN/> .

SELECT ?numEmployees WHERE {
  ?manuf a iof-core:Manufacturer ;
          rdfs:label ?name ;
          sdk:hasNumberOfEmployees ?numEmployees .
  FILTER(CONTAINS(LCASE(STR(?name)), "steel"))
}
LIMIT 1

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?name WHERE {
  ?manuf a sdk:Manufacturer ;
          rdfs:label ?name ;
          sdk:hasCertificate ?cert .
  ?cert a sdk:ISO9001 .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?naicsText WHERE {
  sdk:naics-332996.0-inst a sdk:NAICS332996.0 ;
    sdk:hasNAICSTextValue ?naicsText ;
    sdk:hasNAICSCodeValue ?code .
  FILTER(?code = "332996.0"^^xsd:integer)
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>

SELECT ?naicsCode ?naicsText
WHERE {
  ?naicsInst a sdk:NAICS332996.0 ;
              sdk:hasNAICSTextValue ?naicsText ;
              sdk:hasNAICSCodeValue ?naicsCode .
  FILTER(CONTAINS(?naicsText, "PIPE AND PIPE FITTING")) .
}

PREFIX sdk: <http://asu.edu/semantics/SUDOKN/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?capability ?name
WHERE {
  ?capability a sdk:MachiningCapability ;
              rdfs:label ?name .
  FILTER (str(?name) = "Machining")
}
